<?php /** New ticket dialog (inbox and customer 360). Expects $d from sl_csBase. */ ?>
<div class="sl-dialog" id="cs-new" hidden><form class="sl-modal" data-cs-form="create" data-cs-redirect="support_ticket.php?id={id}" role="dialog" aria-label="New ticket" autocomplete="off">
<div class="row g10"><span class="sl-tile"><i class="ic i-ticket" aria-hidden="true"></i></span><div class="col grow"><b class="fw5">New ticket</b><span class="mut sm">For a phone call, a walk-in or a staff request. Chats and web requests open tickets by themselves.</span></div></div>
<label class="row g8 sm"><span class="sl-toggle" role="switch" aria-checked="false" aria-label="Staff request"><input type="hidden" name="is_internal" value="0"></span>Staff request (no customer)</label>
<div class="grid cols2" style="gap:10px"><label class="sl-field"><span class="sl-lab">Customer</span><input class="sl-in" type="search" placeholder="Name, e-mail, phone or locker" data-cs-custq="cs-new-list" data-cs-target="#cs-new-cust" value="<?= h($d['customerPrefillName'] ?? '') ?>"><input type="hidden" name="customer_id" id="cs-new-cust" value="<?= (int) ($d['customerPrefill'] ?? 0) ?>"><div id="cs-new-list" class="col g4"></div></label>
<label class="sl-field"><span class="sl-lab">How did it come in?</span><label class="sl-sel native"><select name="channel"><?php foreach ($d['channels'] as $k => $l): if ($k === 'web') continue; ?><option value="<?= h($k) ?>" <?= $k === 'phone' ? 'selected' : '' ?>><?= h($l) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></label></label></div>
<label class="sl-field"><span class="sl-lab">Subject</span><input class="sl-in" name="subject" maxlength="190" required></label>
<div class="grid cols3" style="gap:10px"><label class="sl-field"><span class="sl-lab">Topic</span><label class="sl-sel native"><select name="category"><?php foreach ($d['categories'] as $k => $l): ?><option value="<?= h($k) ?>"><?= h($l) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></label></label>
<label class="sl-field"><span class="sl-lab">Priority</span><label class="sl-sel native"><select name="priority"><?php foreach ($d['priorities'] as $k => $l): ?><option value="<?= h($k) ?>" <?= $k === 'normal' ? 'selected' : '' ?>><?= h($l) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></label></label>
<label class="sl-field"><span class="sl-lab">Team</span><label class="sl-sel native"><select name="team_id"><option value="0">Default team</option><?php foreach ($d['teams'] as $t): ?><option value="<?= (int) $t['id'] ?>"><?= h($t['name']) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></label></label></div>
<label class="sl-field"><span class="sl-lab">Details (saved as an internal note)</span><textarea class="sl-in" name="description" rows="3"></textarea></label>
<label class="row g8 sm"><span class="sl-toggle" role="switch" aria-checked="false" aria-label="Send acknowledgement"><input type="hidden" name="notify_customer" value="0"></span>Send the customer the acknowledgement with the ticket number</label>
<div class="row g8"><button type="submit" class="sl-btn"><i class="ic ic-sm i-plus" aria-hidden="true"></i>Create ticket</button><button type="button" class="sl-btn ghost" data-sl-close>Cancel</button></div>
</form></div>
